<?php
namespace App\Application\Documentos;
use App\Application\Autorizacion\AutorizacionContextual; use App\Application\Contexto\ContextoOperativo; use App\Models\{Documento,DocumentoVersion,User}; use Illuminate\Auth\Access\AuthorizationException; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class SometerVersionDocumento { public function __construct(private readonly AutorizacionContextual $autorizacion,private readonly ConsultaDocumentosContextuales $consulta,private readonly RegistrarActuacionDocumento $actuaciones){} public function ejecutar(ContextoOperativo $c,User $u,Documento $d,DocumentoVersion $v):void{$d=$this->consulta->resolver($c,$d->id);$v=$this->consulta->resolverVersion($c,$d,$v->id);if(!$this->autorizacion->tienePermiso($c,'documentos.gestionar'))throw new AuthorizationException();DB::transaction(function()use($d,$v,$u){Documento::query()->whereKey($d->id)->lockForUpdate()->firstOrFail();$v=DocumentoVersion::query()->whereKey($v->id)->lockForUpdate()->firstOrFail();if($v->estado->value!=='borrador')throw ValidationException::withMessages(['version'=>['Solo se puede someter una Versión en borrador.']]);if(DocumentoVersion::query()->where('documento_id',$d->id)->where('estado','pendiente_aprobacion')->exists())throw ValidationException::withMessages(['version'=>['Ya existe una Versión pendiente de aprobación.']]);$v->update(['estado'=>'pendiente_aprobacion','sometida_por_user_id'=>$u->id,'nombre_sometedor'=>$u->name,'sometida_at'=>now()]);$this->actuaciones->registrar($d,$v,$u,'version_sometida','Sometió la Versión para aprobación.');});}}
